"""Independent reference implementations and a brute-force optimum."""
import bisect
import ipaddress

U = 1 << 128
WIDTH = (16, 8, 4)
LANES = (4, 8, 16)


def text_of(value):
    return str(ipaddress.IPv6Address(value))


def reference_runs(routes):
    entries = [(s, l, h) for (s, l), h in routes.items()]
    bounds = {0}
    for s, l, _h in entries:
        bounds.add(s)
        if l > 0:
            end = s + (1 << (128 - l))
            if end < U:
                bounds.add(end)
    out = []
    for b in sorted(bounds):
        best, bestlen = None, -1
        for s, l, h in entries:
            if s <= b < s + (1 << (128 - l)) and l > bestlen:
                bestlen, best = l, h
        hop = best if bestlen >= 0 else None
        if out and out[-1][1] == hop:
            continue
        out.append((b, hop))
    if not out:
        out = [(0, None)]
    return ([x[0] for x in out], [x[1] for x in out])


def compositions(total, parts):
    if parts == 1:
        yield (total,)
        return
    for head in range(1, total - parts + 2):
        for rest in compositions(total - head, parts - 1):
            yield (head,) + rest


def brute_optimum(starts, hops, bursts, C, hit, miss, dec):
    """Exact minimum (work, image_pages) over every legal layout."""
    R = len(starts)
    weights = [0] * R
    hitsets = []
    for repeat, addresses in bursts:
        runs = [bisect.bisect_right(starts, a) - 1 for a in addresses]
        for k in runs:
            weights[k] += repeat
        hitsets.append((repeat, set(runs)))
    wsum = [0]
    for x in weights:
        wsum.append(wsum[-1] + x)

    def Q(i, j):
        return wsum[j] - wsum[i]

    def T(i, j):
        t = 0
        for repeat, hs in hitsets:
            if any(i <= k < j for k in hs):
                t += repeat
        return t

    def ok(i, s, m):
        if m == 0:
            return True
        spread = starts[i + s - 1] - starts[i]
        return spread < (1 << (64 if m == 1 else 32))

    memo = {}

    def options(i, s):
        if (i, s) in memo:
            return memo[(i, s)]
        out = []
        if s <= 8:
            for m in range(3):
                if not ok(i, s, m):
                    continue
                P = (32 + s * WIDTH[m] + 63) // 64
                coeff = (s + LANES[m] - 1) // LANES[m] + dec[m]
                base = coeff * Q(i, i + s)
                for cached in (0, 1):
                    work = base + P * (hit if cached else miss) * T(i, i + s)
                    out.append((work, P, P if cached else 0,
                                [('leaf', i, s, m, cached)]))
        if s >= 2:
            for b in range(2, min(9, s) + 1):
                for m in range(3):
                    if not ok(i, s, m):
                        continue
                    P = (32 + 4 * b + (b - 1) * WIDTH[m] + 63) // 64
                    coeff = ((b - 1) + LANES[m] - 1) // LANES[m] + dec[m]
                    node_base = coeff * Q(i, i + s)
                    node = [(P * (hit if cached else miss) * T(i, i + s) + node_base,
                             P, P if cached else 0, b, m, cached)
                            for cached in (0, 1)]
                    for comp in compositions(s, b):
                        parts, at = [], i
                        for span in comp:
                            parts.append(options(at, span))
                            at += span
                        for combo in _product(parts):
                            for (work, _p, resident, b_, m_, cached_) in node:
                                cwork = work + sum(x[0] for x in combo)
                                cpages = P + sum(x[1] for x in combo)
                                cres = resident + sum(x[2] for x in combo)
                                tree = [('int', i, s, b_, m_, cached_,
                                         [x[3] for x in combo])]
                                out.append((cwork, cpages, cres, tree))
        memo[(i, s)] = out
        return out

    best = None
    for work, pages, resident, tree in options(0, R):
        if resident > C:
            continue
        cand = (work, pages)
        if best is None or cand < best:
            best = cand
    return best


def _product(groups):
    if not groups:
        yield ()
        return
    for head in groups[0]:
        for rest in _product(groups[1:]):
            yield (head,) + rest


def reference_changes(left, right):
    s0, h0 = left
    s1, h1 = right
    bounds = sorted(set(s0) | set(s1))
    rows = []
    for k, start in enumerate(bounds):
        end = bounds[k + 1] if k + 1 < len(bounds) else U
        old = h0[bisect.bisect_right(s0, start) - 1]
        new = h1[bisect.bisect_right(s1, start) - 1]
        if old == new:
            continue
        if rows and rows[-1][1] == start and rows[-1][2:] == [old, new]:
            rows[-1][1] = end
        else:
            rows.append([start, end, old, new])
    return [[("%032x" % a), ("%032x" % b), o, n] for a, b, o, n in rows]
